# owner: platform
"""Weekly timesheet rows built from a list of shifts."""

from typing import Dict, List
from hourglass.models import Shift
from hourglass.errors import ProjectError
from collections import defaultdict

def _tally(shifts: List[Shift]) -> Dict[str, List[int]]:
    stats = defaultdict(lambda: [0, 0])
    for shift in shifts:
        if not shift.worker.strip():
            raise ProjectError("blank worker name")
        stats[shift.worker][0] += 1
        stats[shift.worker][1] += shift.span.minutes
    return stats

def _row(name: str, stat: List[int]) -> str:
    count, minutes = stat
    hours = minutes / 60
    return f"{name}: {count} shifts, {hours:.1f} hours"

def _order(stats: Dict[str, List[int]]) -> List[str]:
    def hours(name):
        return (-stats[name][1], name)
    return sorted(stats, key=hours)

# ---
def timesheet_rows(shifts: List[Shift]) -> List[str]:
    """One line per worker, most hours first."""
    if not shifts:
        raise ProjectError("no shifts to report")
    stats = _tally(shifts)
    names = _order(stats)
    return [_row(key, stats[key]) for key in names]
